DO WHILE SWAPPED;
   SWAPPED = 0;
   DO I = 1 TO N - 1;
      IF DATA1(I - 1) > DATA1(I) THEN DO;
         T = DATA1(I - 1);
         DATA1(I - 1) = DATA1(I);
         DATA1(I) = T;
         SWAPPED = 1;
      END;
   END;
END;
